-- =====================================================================\n-- V10: tablas que los delegates de Partes 1-2 ya usaban\n--      sin que existieran en Flyway. Sin esto, los BPMN fallan en runtime.\n-- =====================================================================\n\n-- ---------------------------------------------------------------------\n-- ProjectDocuments: RFI / ChangeOrder / Submittal\n-- ---------------------------------------------------------------------\nCREATE TYPE rfi_status AS ENUM (\n  'DRAFT','ROUTED','ASSIGNED','RESPONDED','ESCALATED','CLOSED','CANCELLED'\n);\n\nCREATE TABLE rfi (\n  tenant_id        uuid NOT NULL,\n  rfi_id           uuid NOT NULL,\n  project_id       uuid NOT NULL,\n  work_package_id  uuid,\n  rfi_number       varchar(40) NOT NULL,\n  title            varchar(300) NOT NULL,\n  description      text NOT NULL,\n  status           rfi_status NOT NULL DEFAULT 'DRAFT',\n  assigned_to_role varchar(60),\n  assigned_to      uuid,\n  deadline         date,\n  responded_at     timestamptz,\n  responded_by     uuid,\n  response_text    text,\n  document_id      uuid,\n  created_by       uuid NOT NULL,\n  aggregate_version bigint NOT NULL DEFAULT 1,\n  created_at       timestamptz NOT NULL DEFAULT now(),\n  updated_at       timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, rfi_id),\n  UNIQUE (tenant_id, project_id, rfi_number)\n);\nCREATE INDEX idx_rfi_status ON rfi (tenant_id, project_id, status);\nCREATE INDEX idx_rfi_assigned ON rfi (tenant_id, assigned_to_role)\n  WHERE status IN ('ROUTED','ASSIGNED');\n\n-- Política determinista de asignación (no se inventa en runtime)\n-- Surrogate PK: project_id/work_package_id pueden ser NULL (fallback)\nCREATE TABLE rfi_routing_policy (\n  tenant_id        uuid NOT NULL,\n  policy_id        uuid NOT NULL DEFAULT gen_random_uuid(),\n  project_id       uuid,\n  work_package_id  uuid,\n  assigned_to_role varchar(60) NOT NULL,\n  priority         int NOT NULL DEFAULT 100,\n  PRIMARY KEY (tenant_id, policy_id)\n);\n-- Unicidad lógica: un solo fallback global, uno por project, uno por WP\nCREATE UNIQUE INDEX uq_rfi_routing_global\n  ON rfi_routing_policy (tenant_id)\n  WHERE project_id IS NULL AND work_package_id IS NULL;\nCREATE UNIQUE INDEX uq_rfi_routing_project\n  ON rfi_routing_policy (tenant_id, project_id)\n  WHERE project_id IS NOT NULL AND work_package_id IS NULL;\nCREATE UNIQUE INDEX uq_rfi_routing_wp\n  ON rfi_routing_policy (tenant_id, project_id, work_package_id)\n  WHERE work_package_id IS NOT NULL;\n\nCREATE TYPE change_order_status AS ENUM (\n  'DRAFT','SUBMITTED','UNDER_REVIEW','APPROVED','REJECTED','IMPLEMENTED','CANCELLED'\n);\n\nCREATE TABLE change_order (\n  tenant_id         uuid NOT NULL,\n  change_order_id   uuid NOT NULL,\n  project_id        uuid NOT NULL,\n  contract_id       uuid NOT NULL,\n  work_package_id   uuid,\n  co_number         varchar(40) NOT NULL,\n  title             varchar(300) NOT NULL,\n  justification     text NOT NULL,\n  amount            numeric(18,2) NOT NULL,\n  status            change_order_status NOT NULL DEFAULT 'DRAFT',\n  approval_group    varchar(60),\n  approved_by       uuid,\n  approved_at       timestamptz,\n  linked_rfi_id     uuid,\n  created_by        uuid NOT NULL,\n  aggregate_version bigint NOT NULL DEFAULT 1,\n  created_at        timestamptz NOT NULL DEFAULT now(),\n  updated_at        timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, change_order_id),\n  UNIQUE (tenant_id, project_id, co_number)\n);\n\nCREATE TYPE submittal_status AS ENUM (\n  'DRAFT','SUBMITTED','APPROVED','APPROVED_AS_NOTED','REVISE_AND_RESUBMIT','REJECTED'\n);\n\nCREATE TABLE submittal (\n  tenant_id      uuid NOT NULL,\n  submittal_id   uuid NOT NULL,\n  project_id     uuid NOT NULL,\n  work_package_id uuid,\n  submittal_number varchar(40) NOT NULL,\n  title          varchar(300) NOT NULL,\n  status         submittal_status NOT NULL DEFAULT 'DRAFT',\n  document_id    uuid NOT NULL,\n  reviewer_role  varchar(60),\n  reviewed_at    timestamptz,\n  created_by     uuid NOT NULL,\n  aggregate_version bigint NOT NULL DEFAULT 1,\n  created_at     timestamptz NOT NULL DEFAULT now(),\n  updated_at     timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, submittal_id),\n  UNIQUE (tenant_id, project_id, submittal_number)\n);\n\n-- ---------------------------------------------------------------------\n-- Bidding\n-- ---------------------------------------------------------------------\nCREATE TYPE bid_package_status AS ENUM (\n  'DRAFT','OPEN','RECEIVING','EVALUATING','AWARDED','CANCELLED'\n);\nCREATE TYPE bid_status AS ENUM (\n  'RECEIVED','DISQUALIFIED','SELECTED','NOT_SELECTED'\n);\n\nCREATE TABLE bid_package (\n  tenant_id       uuid NOT NULL,\n  bid_package_id  uuid NOT NULL,\n  project_id      uuid NOT NULL,\n  work_package_id uuid,\n  name            varchar(300) NOT NULL,\n  status          bid_package_status NOT NULL DEFAULT 'DRAFT',\n  bid_deadline    timestamptz,\n  awarded_bid_id  uuid,\n  awarded_at      timestamptz,\n  created_by      uuid NOT NULL,\n  aggregate_version bigint NOT NULL DEFAULT 1,\n  created_at      timestamptz NOT NULL DEFAULT now(),\n  updated_at      timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, bid_package_id)\n);\n\nCREATE TABLE bid (\n  tenant_id       uuid NOT NULL,\n  bid_id          uuid NOT NULL,\n  bid_package_id  uuid NOT NULL,\n  bidder_id       uuid NOT NULL,\n  amount          numeric(18,2) NOT NULL,\n  currency        char(3) NOT NULL DEFAULT 'USD',\n  status          bid_status NOT NULL DEFAULT 'RECEIVED',\n  submitted_at    timestamptz NOT NULL DEFAULT now(),\n  document_id     uuid,\n  PRIMARY KEY (tenant_id, bid_id)\n);\nCREATE INDEX idx_bid_by_package ON bid (tenant_id, bid_package_id, amount);\n\n-- ---------------------------------------------------------------------\n-- Permits\n-- ---------------------------------------------------------------------\nCREATE TYPE permit_status AS ENUM (\n  'DRAFT','SUBMITTED','IN_REVIEW','OBSERVED','APPROVED','DENIED','EXPIRED','CANCELLED'\n);\n\nCREATE TABLE permit_application (\n  tenant_id       uuid NOT NULL,\n  permit_id       uuid NOT NULL,\n  project_id      uuid NOT NULL,\n  site_id         uuid,\n  jurisdiction    varchar(40) NOT NULL,\n  permit_type     varchar(60) NOT NULL,\n  permit_number   varchar(80),\n  status          permit_status NOT NULL DEFAULT 'DRAFT',\n  submitted_at    timestamptz,\n  authority_ref   varchar(120),\n  deadline        date,\n  approved_at     timestamptz,\n  valid_until     date,\n  document_id     uuid,\n  created_by      uuid NOT NULL,\n  aggregate_version bigint NOT NULL DEFAULT 1,\n  created_at      timestamptz NOT NULL DEFAULT now(),\n  updated_at      timestamptz NOT NULL DEFAULT now(),\n  PRIMARY KEY (tenant_id, permit_id)\n);\nCREATE INDEX idx_permit_status ON permit_application (tenant_id, project_id, status);\n\n-- ---------------------------------------------------------------------\n-- RLS en todas las tablas nuevas\n-- ---------------------------------------------------------------------\nALTER TABLE rfi                    ENABLE ROW LEVEL SECURITY;\nALTER TABLE rfi_routing_policy     ENABLE ROW LEVEL SECURITY;\nALTER TABLE change_order           ENABLE ROW LEVEL SECURITY;\nALTER TABLE submittal              ENABLE ROW LEVEL SECURITY;\nALTER TABLE bid_package            ENABLE ROW LEVEL SECURITY;\nALTER TABLE bid                    ENABLE ROW LEVEL SECURITY;\nALTER TABLE permit_application     ENABLE ROW LEVEL SECURITY;\n\nDO $$\nDECLARE t text;\nBEGIN\n  FOR t IN SELECT unnest(ARRAY[\n    'rfi','rfi_routing_policy','change_order','submittal',\n    'bid_package','bid','permit_application'\n  ]) LOOP\n    EXECUTE format(\n      'CREATE POLICY ti_%I ON %I USING (tenant_id = current_setting(''app.tenant_id'')::uuid)',\n      t, t);\n  END LOOP;\nEND $$;\n\n-- ---------------------------------------------------------------------\n-- Semilla de política de asignación para el tenant default\n-- ---------------------------------------------------------------------\nINSERT INTO rfi_routing_policy\n  (tenant_id, project_id, work_package_id, assigned_to_role, priority)\nSELECT '00000000-0000-0000-0000-000000000001', NULL, NULL, 'PROJECT_ENGINEER', 100\nWHERE NOT EXISTS (\n  SELECT 1 FROM rfi_routing_policy\n   WHERE tenant_id = '00000000-0000-0000-0000-000000000001'\n     AND project_id IS NULL AND work_package_id IS NULL\n);